# Define annotation categories for different physics frameworks
string_theory = {"Twist", "Tension", "Torsion"}
quantum_field_theory = {"ħ", "λ_C", "α", "e", "μ₀"}
relativity = {"c", "G", "ℓ_P", "Curvature", "Sweep"}
classical_physics = {"r_e", "ε₀", "k_B", "Footprint", "Elasticity", "Compliance"}

# Assign colors based on physics domain
node_colors = []
for node in G.nodes:
    if node in string_theory:
        node_colors.append("violet")  # String theory elements
    elif node in quantum_field_theory:
        node_colors.append("orange")  # QFT/Standard Model
    elif node in relativity:
        node_colors.append("red")     # Relativity
    elif node in classical_physics:
        node_colors.append("gold")    # Classical physics
    elif node in constants.values():
        node_colors.append("lightblue")  # Unmarked constants
    else:
        node_colors.append("lightgreen")  # Default for constraints

# Plotting with annotations
plt.figure(figsize=(14, 10))
nx.draw_networkx_nodes(G, pos, node_color=node_colors, node_size=1500)
nx.draw_networkx_edges(G, pos, arrows=True)
nx.draw_networkx_labels(G, pos, font_size=10, font_weight='bold')
plt.title("Annotated Constraint Network: Constants and Theoretical Domains", fontsize=14)
plt.axis('off')

# Create custom legend
import matplotlib.patches as mpatches
legend_patches = [
    mpatches.Patch(color='violet', label='String Theory'),
    mpatches.Patch(color='orange', label='Quantum Field Theory'),
    mpatches.Patch(color='red', label='Relativity'),
    mpatches.Patch(color='gold', label='Classical Physics'),
    mpatches.Patch(color='lightgreen', label='Chronostructural Constraints'),
    mpatches.Patch(color='lightblue', label='Constants')
]
plt.legend(handles=legend_patches, loc='lower left')
plt.tight_layout()
plt.show()

